arguments.command:
python3 -c "
import pandas as pd
import json

df = pd.read_csv('data.csv')

# City-level median price (only for cities with valid price data)
cities_with_price = {}
for city in sorted(df['city'].unique()):
    prices = df[df['city'] == city]['price'].dropna()
    if len(prices) > 0:
        cities_with_price[city] = {'median': float(prices.median()), 'mean': float(prices.mean()), 'n': len(prices)}

print('Cities with price data:', json.dumps(cities_with_price, indent=2))

# Median price by room type for the pricing section
print()
print('=== Median Price by Room Type per City ===')
for city in sorted(df['city'].unique()):
    city_df = df[df['city'] == city]
    row = {'city': city}
    for rt in ['Entire home/apt', 'Private room', 'Shared room', 'Hotel room']:
        rt_df = city_df[city_df['room_type'] == rt]
        prices = rt_df['price'].dropna()
        if len(prices) > 0:
            row[rt] = {'median': float(prices.median()), 'n': len(prices)}
        else:
            row[rt] = {'median': None, 'n': len(rt_df)}
    print(f'{city}: {row}')
" 2>&1

