    --surface: #ffffff;
    --border: #e2e6ec;
    --text: #1a1e29;
    --text-muted: #6b7280;
    --accent: #2563eb;
    --accent-light: #dbeafe;
    --accent-dark: #1e40af;
    --success: #059669;
    --warning: #d97706;
    --danger: #dc2626;
    --purple: #7c3aed;
  }

  body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.6;
    font-size: 15px;
  }

  .report-header {
    background: linear-gradient(135deg, #1e3a5f 0%, #2563eb 100%);
    color: white;
    padding: 60px 40px;
  }

  .report-header .eyebrow {
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 1.5px;
    text-transform: uppercase;
    color: #93c5fd;
    margin-bottom: 16px;
  }

  .report-header h1 {
    font-size: 32px;
    font-weight: 800;
    line-height: 1.2;
    margin-bottom: 16px;
    max-width: 760px;
  }

  .report-header .subtitle {
    font-size: 16px;
    color: #bfdbfe;
    max-width: 680px;
    line-height: 1.7;
  }

  .report-meta {
    margin-top: 28px;
    padding-top: 20px;
    border-top: 1px solid rgba(255,255,255,0.2);
    display: flex;
    gap: 32px;
    font-size: 12px;
    color: #93c5fd;
  }

  .container {
    max-width: 1100px;
    margin: 0 auto;
    padding: 40px 40px 80px;
  }

  .section {
    background: var(--surface);
    border-radius: 12px;
    border: 1px solid var(--border);
    padding: 36px 40px;
    margin-bottom: 28px;
  }

  .section-header {
    margin-bottom: 28px;
  }

  .section-number {
    display: inline-block;
    background: var(--accent);
    color: white;
    font-size: 11px;
    font-weight: 700;
    width: 26px;
    height: 26px;
    border-radius: 50%;
    text-align: center;
    line-height: 26px;
    margin-bottom: 10px;
  }

  h2 {
    font-size: 20px;
    font-weight: 700;
    color: var(--text);
    margin-bottom: 6px;
  }

  .section-intro {
    font-size: 14px;
    color: var(--text-muted);
    line-height: 1.7;
  }

  /* KPI Cards */
  .kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 16px;
  }

  .kpi-card {
    background: var(--bg);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 20px;
  }

  .kpi-label {
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.8px;
    text-transform: uppercase;
    color: var(--text-muted);
    margin-bottom: 8px;
  }

  .kpi-value {
    font-size: 28px;
    font-weight: 800;
    color: var(--accent-dark);
    line-height: 1;
    margin-bottom: 6px;
  }

  .kpi-sub {
    font-size: 12px;
    color: var(--text-muted);
  }

  .kpi-note {
    font-size: 11px;
    color: var(--warning);
    margin-top: 6px;
    font-style: italic;
  }

  /* Tables */
  .data-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 13px;
  }

  .data-table thead th {
    background: #f1f4f8;
    padding: 10px 14px;
    text-align: left;
    font-weight: 600;
    font-size: 11px;
    letter-spacing: 0.6px;
    text-transform: uppercase;
    color: var(--text-muted);
    border-bottom: 2px solid var(--border);
  }

  .data-table tbody tr {
    border-bottom: 1px solid var(--border);
  }

  .data-table tbody tr:last-child {
    border-bottom: none;
  }

  .data-table tbody td {
    padding: 12px 14px;
  }

  .data-table tbody tr:hover {
    background: #f8fafc;
  }

  .text-right { text-align: right; }
  .text-center { text-align: center; }

  .badge {
    display: inline-block;
    padding: 2px 8px;
    border-radius: 12px;
    font-size: 11px;
    font-weight: 600;
  }

  .badge-high { background: #fee2e2; color: #991b1b; }
  .badge-medium { background: #fef3c7; color: #92400e; }
  .badge-low { background: #d1fae5; color: #065f46; }

  .no-data {
    color: var(--text-muted);
    font-style: italic;
    font-size: 12px;
  }

  /* Chart containers */
  .chart-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
    margin-bottom: 32px;
  }

  .chart-container {
    background: var(--bg);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 20px;
  }

  .chart-container canvas {
    max-height: 320px;
  }

  .chart-container-wide {
    grid-column: 1 / -1;
  }

  .chart-title {
    font-size: 13px;
    font-weight: 600;
    color: var(--text);
    margin-bottom: 14px;
    padding-bottom: 10px;
    border-bottom: 1px solid var(--border);
  }

  /* Key takeaways */
  .takeaway-grid {
    display: grid;
    gap: 16px;
  }

  .takeaway-item {
    display: flex;
    gap: 16px;
    padding: 20px;
    background: var(--bg);
    border-radius: 10px;
    border: 1px solid var(--border);
  }

  .takeaway-number {
    flex-shrink: 0;
    width: 32px;
    height: 32px;
    background: var(--accent);
    color: white;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 700;
    font-size: 14px;
  }

  .takeaway-content h4 {
    font-size: 14px;
    font-weight: 700;
    margin-bottom: 4px;
    color: var(--text);
  }

  .takeaway-content p {
    font-size: 13px;
    color: var(--text-muted);
    line-height: 1.6;
  }

  .data-note {
    font-size: 12px;
    color: var(--text-muted);
    border-left: 3px solid var(--warning);
    padding: 10px 16px;
    background: #fffbeb;
    border-radius: 0 8px 8px 0;
    margin-top: 20px;
  }

  .color-legend {
    display: flex;
    gap: 20px;
    flex-wrap: wrap;
    margin-top: 12px;
    font-size: 11px;
    color: var(--text-muted);
  }

  .color-legend span {
    display: flex;
    align-items: center;
    gap: 5px;
  }

  .color-dot {
    width: 10px;
    height: 10px;
    border-radius: 50%;
    display: inline-block;
  }

  .two-col-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 32px;
  }

  @media (max-width: 768px) {
    .chart-row, .two-col-grid { grid-template-columns: 1fr; }
    .report-header { padding: 40px 24px; }
    .container { padding: 24px 20px 60px; }
    .section { padding: 24px 20px; }
  }
</style>
</head>
<body>

<header class="report-header">
  <div class="eyebrow">Hospitality Industry Analysis</div>
  <h1>Global Airbnb Market Comparison: Pricing, Supply &amp; Guest Demand Across 10 Major Cities</h1>
  <p class="subtitle">A comprehensive cross-city analysis of Airbnb listings across New York, London, Paris, Tokyo, Barcelona, Los Angeles, Amsterdam, Bangkok, Rome, and Sydney — examining pricing dynamics, room-type distribution, host concentration, and guest engagement patterns.</p>
  <div class="report-meta">
    <span>Dataset: Inside Airbnb — March 2026 scrape</span>
    <span>50,000 listings across 7 cities</span>
    <span>10 cities specified · 3 cities absent from dataset</span>
  </div>
</header>

<div class="container">

  <!-- SECTION 1: MARKET OVERVIEW -->
