        <table class="data-table" style="font-size: 12px;">
          <thead>
            <tr>
              <th>City</th>
              <th class="text-right">Median</th>
              <th class="text-right">Mean</th>
              <th class="text-right">25th %ile</th>
              <th class="text-right">75th %ile</th>
            </tr>
          </thead>
          <tbody>
            <tr><td>Amsterdam</td><td class="text-right">$222</td><td class="text-right">$266</td><td class="text-right">$140</td><td class="text-right">$350</td></tr>
            <tr><td>Bangkok</td><td class="text-right">$1,400</td><td class="text-right">$2,337</td><td class="text-right">$919</td><td class="text-right">$2,250</td></tr>
            <tr><td>Barcelona</td><td class="text-right">$132</td><td class="text-right">$190</td><td class="text-right">$72</td><td class="text-right">$215</td></tr>
            <tr><td>London</td><td class="text-right">$135</td><td class="text-right">$210</td><td class="text-right">$75</td><td class="text-right">$220</td></tr>
            <tr><td>Rome</td><td class="text-right">$131</td><td class="text-right">$198</td><td class="text-right">$75</td><td class="text-right">$240</td></tr>
          </tbody>
        </table>
      </div>
    </div>

    <div class="chart-container-wide" style="margin-top: 24px;">
      <div class="chart-title">Price Dispersion: Entire Home/Apt Median vs. Mean (USD) — Room-Type Premium</div>
      <canvas id="priceDispersionChart"></canvas>
    </div>
  </div>

  <!-- SECTION 3: SUPPLY STRUCTURE -->
  <div class="section">
    <div class="section-header">
      <div class="section-number">3</div>
      <h2>Supply Structure &amp; Host Concentration</h2>
      <p class="section-intro">Analyzing room-type distributions and professional vs. individual host prevalence using calculated_host_listings_count &ge; 5 as the threshold for professional hosts.</p>
    </div>

    <div class="kpi-grid">
      <div class="kpi-card">
        <div class="kpi-label">Highest Professional Host Share</div>
        <div class="kpi-value">60.4%</div>
        <div class="kpi-sub">Bangkok — 2,998 of 4,961 listings</div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">Lowest Professional Host Share</div>
        <div class="kpi-value">6.8%</div>
        <div class="kpi-sub">Amsterdam — 120 of 1,770 listings</div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">Highest Entire Home Share</div>
        <div class="kpi-value">88.2%</div>
        <div class="kpi-sub">Paris — dominated by full-unit listings</div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">Lowest Entire Home Share</div>
        <div class="kpi-value">60.2%</div>
        <div class="kpi-sub">Barcelona — highest private room proportion</div>
      </div>
    </div>

    <div class="chart-row" style="margin-top: 28px;">
      <div class="chart-container">
        <div class="chart-title">Professional Host Share by City (% of listings with 5+ listing hosts)</div>
        <canvas id="profHostChart"></canvas>
      </div>
      <div class="chart-container">
        <div class="chart-title">Room-Type Composition by City (%)</div>
        <canvas id="roomTypeStackChart"></canvas>
      </div>
    </div>

    <div style="margin-top: 24px;">
      <table class="data-table">
        <thead>
          <tr>
            <th>City</th>
            <th class="text-right">Professional Hosts<br><span style="font-weight:400;font-size:10px;">(5+ listings)</span></th>
            <th class="text-right">Professional Share</th>
            <th class="text-right">Individual Hosts<br><span style="font-weight:400;font-size:10px;">(1–4 listings)</span></th>
            <th class="text-right">Individual Share</th>
            <th>Interpretation</th>
          </tr>
        </thead>
        <tbody>
          <tr>
            <td><strong>Bangkok</strong></td>
            <td class="text-right">2,998</td>
            <td class="text-right"><span class="badge badge-high">60.4%</span></td>
