      </table>
    </div>
  </div>

  <!-- SECTION 4: GUEST DEMAND -->
  <div class="section">
    <div class="section-header">
      <div class="section-number">4</div>
      <h2>Guest Demand &amp; Review Activity</h2>
      <p class="section-intro">Using number_of_reviews, reviews_per_month, and number_of_reviews_ltm as demand proxies to compare guest engagement across cities and identify seasonal or recency patterns.</p>
    </div>

    <div class="kpi-grid">
      <div class="kpi-card">
        <div class="kpi-label">Highest Avg. Reviews/Month</div>
        <div class="kpi-value">1.77</div>
        <div class="kpi-sub">Rome — strongest guest engagement rate</div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">Highest Total LTM Reviews</div>
        <div class="kpi-value">96,392</div>
        <div class="kpi-sub">London — highest absolute demand despite lower per-listing rate</div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">Most Reviews/Listing (LTM)</div>
        <div class="kpi-value">14.35</div>
