    </div>

    <div class="chart-row" style="margin-top: 28px;">
      <div class="chart-container">
        <div class="chart-title">Average Reviews per Month by City</div>
        <canvas id="rpmChart"></canvas>
      </div>
      <div class="chart-container">
        <div class="chart-title">Total Reviews (Last 12 Months) by City</div>
